:"Morelife Apartments","meta":"Kraków · Zrealizowane"},{"img":"/investments/rudava-park/gallery/rudava-park-01.webp","title":"Rudava Park","meta":"Kraków · W trakcie realizacji"},{"img":"/investments/pod-stokiem-apartamenty/vis/pod-stokiem-apartamenty-01.webp","title":"Apartamenty Pod Stokiem","meta":"Kraków · W trakcie realizacji"},{"img":"/investments/villaverde-wola/gallery/vis-01.webp","title":"Villa Verde","meta":"Kraków · W trakcie realizacji"},{"img":"/investments/pylna-residence/gallery/vis-1.webp","title":"Pylna Residence","meta":"Kraków · Etap projektowy"},{"img":"/investments/the-emaus/gallery/vis-01.webp","title":"The Emaus","meta":"Kraków · Zrealizowane"}],"editable":true,"label":"Realizacje","type":"table"}}},{"id":"process","component":"Process","type":"section","label":"Proces","fields":{"eyebrow":{"value":"Proces","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Jak wygląda współpraca","editable":true,"label":"Nagłówek","type":"string"},"quote":{"value":"Twoje zaangażowanie ograniczamy do minimum - zajmujemy się całą organizacją i realizacją procesu.","editable":true,"label":"Cytat","type":"string"},"steps":{"value":[{"id":"1","icon":"clipboard","title":"Etap przygotowawczy","items":["analiza działki i jej potencjału","wybór optymalnego projektu","weryfikacja dokumentacji","uzyskanie formalności i pozwoleń","przygotowanie harmonogramu i budżetu"]},{"id":"2","icon":"hardhat","title":"Organizacja i rozpoczęcie budowy","items":["wybór sprawdzonych wykonawców","organizacja procesu budowy","zamówienia materiałów","koordynacja dostaw","rozpoczęcie prac budowlanych"]},{"id":"3","icon":"building","title":"Realizacja inwestycji","items":["prowadzenie i koordynacja budowy","bieżąca kontrola jakości","nadzór nad zgodnością z projektem","zarządzanie harmonogramem","regularne raporty postępu"]},{"id":"4","icon":"shield","title":"Kontrola budżetu i jakości","items":["weryfikacja kosztów","kontrola płatności","optymalizacja wydatków","eliminowanie błędów wykonawczych"]},{"id":"5","icon":"key","title":"Wykończenie i odbiory","items":["koordynacja prac wykończeniowych","nadzór nad instalacjami","odbiory techniczne","usuwanie usterek","przekazanie gotowego domu"]},{"id":"6","icon":"key","title":"Gwarancja jakości","items":["gwarancja na wykonane prace","przekazanie kompletnej dokumentacji","wsparcie po zakończeniu inwestycji","sprawna obsługa ewentualnych usterek","opieka doświadczonego zespołu"]}],"editable":true,"label":"Kroki","type":"table"}}},{"id":"benefits","component":"Benefits","type":"section","label":"Korzyści","fields":{"eyebrow":{"value":"Twoje korzyści","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Budujemy domy premium kompleksowo","editable":true,"label":"Nagłówek","type":"string"},"text":{"value":"Od działki do gotowego domu - jeden partner odpowiedzialny za każdy etap Twojej inwestycji.","editable":true,"label":"Tekst","type":"string"},"benefits":{"value":["Oszczędzasz czas - nie musisz codziennie nadzorować budowy","Ograniczasz stres - przejmujemy odpowiedzialność za realizację","Kontrolujesz koszty - pilnujemy budżetu inwestycji","Otrzymujesz sprawdzone rozwiązania i technologie","Zyskujesz wysoką jakość wykonania","Masz jeden zespół odpowiedzialny za cały proces","Budujesz dom bez angażowania się w codzienne problemy budowy","Masz gwarancję jakości i wsparcia również po zakończeniu inwestycji"],"editable":true,"label":"Korzyści","type":"table"}}},{"id":"knowledge","component":"Knowledge","type":"section","label":"Baza wiedzy","fields":{"eyebrow":{"value":"Baza wiedzy","editable":true,"label":"Nadtytuł","type":"string"},"header":{"value":"Ekspercka wiedza dla inwestorów","editable":true,"label":"Nagłówek","type":"string"},"text":{"value":"Sprawdź praktyczne materiały przygotowane przez ekspertów KGD Building i dowiedz się, jak bezpiecznie przeprowadzić inwestycję od początku do końca.","editable":true,"label":"Tekst","type":"string"},"guides":{"value":[{"title":"10 błędów, które kosztują inwestorów najwięcej podczas budowy domu","desc":"Dowiedz się, jak uniknąć najczęstszych problemów.","href":"https://kgd-group.pl/admin/assets/link/6a5a32ad170aa43d7fcf2f1a","cta":"Pobierz poradnik"},{"title":"Na co zwrócić uwagę wybierając firmę do realizacji i prowadzenia budowy?","desc":"Sprawdź najważniejsze kryteria wyboru.","href":"https://kgd-group.pl/admin/assets/link/6a5a32ae170aa43d7ffbe895","cta":"Pobierz poradnik"}],"editable":true,"label":"Poradniki","type":"table"}}},{"id":"deweloper","component":"Deweloper","type":"section","label":"O KGD","fields":{"header":{"value":"KGD - Deweloper","editable":true,"label":"Nagłówek","type":"string"},"aboutKGD":{"value":"KGD Building stanowi część Krakowskiej Grupy Deweloperskiej (KGD), specjalizującej się w realizacji inwestycji mieszkaniowych w segmencie premium w najbardziej prestiżowych lokalizacjach Krakowa oraz okolic. Doświadczenie grupy obejmuje projekty o łącznej skali przekraczającej 55 000 m² PUM, realizowane w oparciu o wypracowane standardy jakości, organizacji procesu inwestycyjnego oraz współpracy z wyspecjalizowanymi wykonawcami. Każda inwestycja KGD to połączenie dopracowanej architektury, funkcjonalnych rozwiązań oraz wysokiego standardu wykonania.","editable":true,"label":"Tekst o KGD","type":"string"},"buttonLabel":{"value":"Dowiedz się więcej","editable":true,"label":"Etykieta przycisku","type":"string"}}},{"id":"contact","component":"Contact","type":"section","label":"Contact","fields":{"heading":{"value":"Kontakt","editable":true,"label":"Nagłówek","type":"string"},"label":{"value":"Masz pytania o nasze inwestycje lub chcesz dowiedzieć się więcej o WOLA JUSTOWSKA INWESTYCJE 2 SPÓŁKA Z OGRANICZONĄ ODPOWIEDZIALZIALNOŚCIĄ? Wypełnij formularz, a skontaktujemy się z Tobą.","editable":true,"label":"Opis","type":"string"},"company":{"value":"WOLA JUSTOWSKA INWESTYCJE 2 SPÓŁKA Z OGRANICZONĄ ODPOWIEDZIALZIALNOŚCIĄ","editable":true,"label":"Nazwa firmy","type":"string"},"addre